"""Freeze code/config after synthetic and isolated historical preflight."""
from common import *
import datetime,importlib.metadata as meta,xml.etree.ElementTree as ET

def main():
 ensure();s=snapshot_check();assert not (OUT/'experiment_manifest.json').exists();assert not (OUT/'local/api_ledger.jsonl').exists()
 assert subprocess.check_output(['git','rev-parse',s['freeze_tag']+'^{commit}'],cwd=REPO,text=True).strip()==s['v1_commit'];assert subprocess.check_output(['git','cat-file','-t',s['freeze_tag']],cwd=REPO,text=True).strip()=='tag'
 for p,h in s['snapshot_hashes'].items():
  raw=subprocess.check_output(['git','show',s['v1_commit']+':components/cfaf/'+p],cwd=REPO);assert hashlib.sha256(raw).hexdigest()==h,p
 xml=ET.parse(OUT/'offline_tests.xml').getroot();suite=next(xml.iter('testsuite'));assert suite.get('failures')=='0';tests=int(suite.get('tests'))
 regression=read(OUT/'regression_audit.json');assert regression['advanced_returncode']==0 and regression['v1_baseline_returncode']==0 and regression['original_returncode']==1
 source=list((ROOT/'src/component_cfaf').rglob('*.py'))+list((ROOT/'tests').rglob('*.py'))+list((ROOT/'tools/v1_1').glob('*.py'))+[ROOT/'examples/v1_1_demo.py',ROOT/'pyproject.toml',ROOT/'requirements.lock']
 from component_cfaf.compact import CompactProposal,COMPACT_PROMPT,CompactSDKProvider
 from component_cfaf.adapters.openai_sdk import strict_schema
 assert CompactSDKProvider.output_cap==1536
 original=read(ROOT/'results/freeze.json');assert sha(ROOT/'results/local/inputs.jsonl')==original['inputs_sha256'];assert sha(ROOT/'results/local/gold.jsonl')==original['gold_sha256'];assert len(rows(ROOT/'results/local/inputs.jsonl'))==30
 deps={d.metadata['Name']:d.version for d in meta.distributions()};write(OUT/'dependency_audit.json',{**read(OUT/'dependency_audit.json'),'isolated_runtime_versions':deps,'own_package_version':meta.version('component-cfaf'),'new_runtime_dependencies':[],'runtime_dependencies_unchanged':True})
 write(OUT/'offline_tests.json',{'status':'PASS','current_package_tests':tests,'original_v1_tests_preserved':54,'new_tests':tests-54,'v1_snapshot_tests':54,'synthetic_demo':read(OUT/'demo_output.json')['status'],'no_external_model_calls':True,'historical_compatibility':'691 passed, 3 explicitly not run to avoid opening complete cached source metadata; one original-suite pre-existing failure retained'})
 write(OUT/'experiment_manifest.json',{'version':'ComponentCFAF-v1.1','branch':s['branch'],'completed_v1_commit':s['v1_commit'],'freeze_tag':s['freeze_tag'],'freeze_tag_object':s['freeze_tag_object'],'frozen_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'elapsed_seconds_at_freeze':ensure(),'source_files':{p.relative_to(ROOT).as_posix():sha(p) for p in sorted(set(source))},'inputs_sha256':sha(ROOT/'results/local/inputs.jsonl'),'gold_sha256':sha(ROOT/'results/local/gold.jsonl'),'v1_exposure_manifest_sha256':sha(ROOT/'results/exposure_manifest.json'),'exact_same_thirty_cases':True,'new_records_or_datasets':0,'model':'gpt-4o-mini','temperature':0,'C1_A_output_cap':2048,'C2_output_cap':1536,'SDK_retries':0,'global_attempt_ceiling':100,'target_max_requests':84,'fresh_A_C1_C2':True,'B_derives_exact_A_no_calls':True,'C1_C2_counterbalanced_order':True,'C1_snapshot_hashes':s['snapshot_hashes'],'compact_schema_sha256':hashlib.sha256(json.dumps(strict_schema(CompactProposal),sort_keys=True).encode()).hexdigest(),'compact_prompt_sha256':hashlib.sha256(COMPACT_PROMPT.encode()).hexdigest(),'token_budget_preflight_sha256':sha(OUT/'token_budget_preflight.json'),'no_post_output_tuning':True,'optional_NLI':'OFF','QASPER_TEST_and_protected_holdouts':'NOT_USED','timing_instrumentation':'Transparent finally-return wrappers around gate/renderer/public validator, same instrumentation for fresh C1/C2. Frozen C1 source bytes are never changed.'})
 (OUT/'BASELINE_FREEZE.md').write_text(f"# Completed v1 freeze\n\nCompleted v1 HEAD: `{s['v1_commit']}`. Its earlier base bfd80bb is not its completion. The worktree was clean before this task. Annotated local tag: `{s['freeze_tag']}`; tag object `{s['freeze_tag_object']}`. It dereferences to the completed v1 commit. All 66 public v1 files and nine original private result files are hashed and preserved; a separate exact source snapshot runs the fresh C1 arm.\n\nThe original 54 tests pass against that immutable snapshot. All third-party versions remain unchanged; only the editable component package release changes to 0.1.1. A/C1 use the original frozen 2048-token prompt/schema configuration in fresh processes; C2 loads current v1.1 code at 1536 tokens. No cached C1 output substitutes for a fresh paired result. A/B use the original ordinary configuration and guard.\n\nAll other worktrees, branches, tags and manuscript remain protected. Only ComponentBasaedCFAF receives new commits. No push/merge is performed. Original v1 manifests, reports, tests and raw outputs are retained, not rewritten; reproduction uses the freeze tag rather than the modified current source tree.\n",encoding='utf-8')
 print('FROZEN',tests,'tests; exact v1 source verified; 30 fixed cases; cap 100; C2 cap 1536; no new records')
if __name__=='__main__':main()
